const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const key = String(j.issueKey || j.ticketKey || "").trim().toUpperCase();
  if (!key) continue;

  const scope = String(j.scope || "").trim().toUpperCase();
  const impact = String(j.businessImpact || "").trim().toUpperCase();
  const proc = String(j.businessProcess || "").trim().toUpperCase();
  const hatVorgabe = scope.length > 0 || impact.length > 0;

  out.push({ json: {
    issueKey: key,
    source: "agent",
    ausloeser: "Erstbewertung durch Jira-Agent",
    vorgabeVorhanden: hatVorgabe,
    vorgabeScope: scope || "UNKNOWN",
    vorgabeBusinessImpact: impact || "UNKNOWN",
    vorgabeBusinessProcess: proc || "UNKNOWN",
    vorgabeSecurityRisk: j.securityRisk === true
  } });
}
return out;

// Verwirft Ereignisse, die fachlich keine Neubewertung rechtfertigen.
//
// RELEVANT enthaelt bewusst NICHT assignee, labels und components.
// Das Governance-Regelwerk schliesst diese als Kriterium aus: eine reine
// personelle Zuweisung ist keine fachliche Weitergabe, Standort und Komponente
// sind keine Level-Kriterien. Ein Modellaufruf darauf koennte per Definition
// nie zu einer Aenderung fuehren.
//
// Ausserdem verworfen: Aenderungen durch RWG.Automate selbst (dieser Workflow
// schreibt nach Jira, sonst Rueckkopplung) und durch die Automation-for-Jira-
// Regel, die bei Anlage Bearbeiter und Faelligkeit setzt. Letztere wuerde
// unmittelbar nach dem Aufruf aus dem Jira-Agent einen zweiten Lauf ausloesen.
//
// Seit 03.09.2026 ausserdem verworfen, beides bewusst NICHT ergebnisneutral:
// - Maschinentickets (Monitoring, Defender, SIEM, RWG.Automate als Melder).
//   Dieselbe Regel wie "Filter Automated Ticket Creator" im RAG-JIRA-Ingest,
//   damit beide Flows dasselbe darunter verstehen. Einzige Abweichung: "siem"
//   nur als ganzes Wort, sonst traefe die Regel auch "Siemensring".
//   Bei Kommentarereignissen liefert Jira weder reporter noch creator mit -
//   dort greifen nur die Regeln auf der Zusammenfassung.
// - Ereignisse an Tickets, die bereits in einem Done-Status stehen (ERLEDIGT,
//   GESCHLOSSEN, ...). Das ist das letzte Ereignis, das dieser Workflow von
//   einem Ticket sieht, denn der Trigger filtert auf statusCategory != Done.
//   Es wird mit abschluss: true weitergegeben; "Anspruch setzen" traegt dann
//   nur die Zeile aus jira_feldpflege_state aus und der Lauf endet.

const IGNORIERTE_KONTEN = [
  "712020:86b7f975-90a6-40c7-9e3b-aff4c9013cb9",
  "557058:f58131cb-b67d-43c7-b30d-6b58d40bd077",
  "712020:2c41da01-c990-498c-814a-aa04c2a3db9f",
  "60242eda988758006893fa52"
];
const RELEVANT = ["status", "description", "summary", "issuetype"];

const MASCHINEN_KONTEN = [
  "712020:86b7f975-90a6-40c7-9e3b-aff4c9013cb9",
  "712020:2c41da01-c990-498c-814a-aa04c2a3db9f",
  "60242eda988758006893fa52"
];
const MASCHINEN_TOKENS = ["rwg_automate", "rwg.automate", "managed.monitoring", "defender-noreply", "defender"];
const MASCHINEN_PRAEFIX = /^\s*\[\s*managed\s*\|\s*monitoring\s*\]/i;
const MASCHINEN_MUSTER = /(intune-checker|snipe-checker|bericht zu kritischen events|aufgabenwarteschlangenprotokoll|\bsiem\b|new vulnerabilities notification)/i;

function istMaschinenticket(fields) {
  const leute = [fields.creator, fields.reporter];
  for (const p of leute) {
    if (!p) continue;
    if (MASCHINEN_KONTEN.indexOf(String(p.accountId || "")) !== -1) return true;
    const text = (String(p.emailAddress || "") + " " + String(p.displayName || "")).toLowerCase();
    for (const t of MASCHINEN_TOKENS) { if (text.indexOf(t) !== -1) return true; }
  }
  const summary = String(fields.summary || "");
  if (MASCHINEN_PRAEFIX.test(summary)) return true;
  if (MASCHINEN_MUSTER.test(summary)) return true;
  return false;
}

const out = [];

for (const it of $input.all()) {
  const e = it.json || {};
  const event = String(e.webhookEvent || "");
  const key = String((e.issue && e.issue.key) || "").trim().toUpperCase();
  if (!key) continue;

  let actor = String((e.user && e.user.accountId) || "");
  if (!actor && e.comment && e.comment.author) actor = String(e.comment.author.accountId || "");
  if (IGNORIERTE_KONTEN.indexOf(actor) !== -1) continue;

  const fields = (e.issue && e.issue.fields) || {};
  if (istMaschinenticket(fields)) continue;

  const kategorie = String(((fields.status && fields.status.statusCategory) || {}).key || "").toLowerCase();
  const abschluss = kategorie === "done";

  if (event.indexOf("comment") !== -1) {
    out.push({ json: { issueKey: key, source: "kommentar", ausloeser: event, abschluss: abschluss } });
    continue;
  }

  const changes = (e.changelog && Array.isArray(e.changelog.items)) ? e.changelog.items : [];
  if (changes.length === 0) continue;

  const felder = [];
  for (const c of changes) {
    const fid = String((c && (c.fieldId || c.field)) || "").toLowerCase();
    if (RELEVANT.indexOf(fid) !== -1) felder.push(fid);
  }
  if (felder.length === 0) continue;

  out.push({ json: { issueKey: key, source: "feldaenderung", ausloeser: felder.join(", "), abschluss: abschluss } });
}

return out;

const SUPPORT_FIELD = "customfield_10777";
const STATUS_GWS = "10373";
const AUTOMATION = ["712020:86b7f975-90a6-40c7-9e3b-aff4c9013cb9", "557058:f58131cb-b67d-43c7-b30d-6b58d40bd077", "712020:2c41da01-c990-498c-814a-aa04c2a3db9f", "60242eda988758006893fa52"];
const cand = $("Kandidat und Konfiguration").first().json || {};
const issue = $input.first().json || {};
const f = issue.fields || {};

function adfText(v) {
  if (v === null || v === undefined) return "";
  if (typeof v === "string") return v;
  if (Array.isArray(v)) return v.map(adfText).join("");
  if (typeof v !== "object") return String(v);
  let s = "";
  if (v.type === "text" && typeof v.text === "string") s += v.text;
  if (v.type === "hardBreak") s += "\n";
  if (Array.isArray(v.content)) s += v.content.map(adfText).join("");
  if (v.type === "paragraph") s += "\n";
  return s;
}

// --- M-5 Signaturbereinigung -------------------------------------------
// Entfernt aus Beschreibung und Kommentartexten, was die fachliche
// Bewertung nicht traegt: Grussformel samt Signaturblock, Kontaktzeilen,
// Postanschriften, rechtliche Fusszeilen und zitierte Vorgaengermails.
//
// KONSERVATIV: Im Zweifel wird nicht abgeschnitten. Bleibt nach der
// Bereinigung zu wenig Text uebrig, gilt das Muster als unsicher erkannt
// und der Originaltext wird verwendet. Diese Faelle zaehlt
// result.bereinigung.
//
// Die Sicherung ist eine absolute Untergrenze, kein Anteil. Ein Anteil
// misst nur, wie lang die Signatur im Verhaeltnis war, nicht ob der
// Schnitt stimmt: ist das Anliegen zwei Saetze lang und die Signatur zehn
// Zeilen, ist ein richtiger Schnitt zwangslaeufig groesser als die
// Haelfte. Die Zeichengrenze fragt stattdessen, ob genug Substanz fuer
// eine Bewertung stehen bleibt.
//
// Zwei Grenzen, weil die Schnittmarken unterschiedlich sicher sind:
// Nach einer Grussformel folgt ein Signaturblock, der die Bewertung nie
// traegt. Nach einem Zitat kann dagegen Inhalt stehen, auf den sich der
// Text davor beruft ("siehe unten"). Bleibt dort nur eine Verweiszeile
// uebrig, wird das Zitat behalten.
//
// Diese beiden Zahlen sind die einzigen Stellschrauben der Bereinigung.
const MIN_REST_ZEICHEN = 40;
const MIN_REST_ZEICHEN_ZITAT = 120;

const GRUSS = /^\s*(viele gr(ue|ü)(ss|ß)e|mit freundlichen gr(ue|ü)(ss|ß)en|beste gr(ue|ü)(ss|ß)e|freundliche gr(ue|ü)(ss|ß)e|liebe gr(ue|ü)(ss|ß)e|vielen dank und viele gr(ue|ü)(ss|ß)e|danke und (viele )?gr(ue|ü)(ss|ß)e|mfg)\s*[,.!]?\s*$/i;
const ZITAT = /^\s*(>|von:|gesendet:|an:|betreff:|-{2,}\s*urspr)/i;
const RECHT = /(vertraulichkeitshinweis|diese e-?mail und etwaige|confidentiality notice|nicht der beabsichtigte empf(ae|ä)nger)/i;
const KONTAKT = /^\s*\|?\s*(telefon|tel\.?|mobil|fax|e-?mail|website|web)\s*:?\s*\\?\\?\s*$/i;
const PLZ = /^\s*.{0,40}\|?\s*\d{5}\s+[A-Za-zÄÖÜäöüß.\- ]{2,40}\s*\|?\s*$/;

let bereinigtAnzahl = 0;
let verworfenAnzahl = 0;

function bereinigeText(s) {
  const roh = String(s || "");
  if (roh.length < MIN_REST_ZEICHEN) return roh;
  const zeilen = roh.split("\n");

  let schnitt = -1;
  let schnittAmZitat = false;
  for (let i = 0; i < zeilen.length; i++) {
    const z = zeilen[i];
    if (GRUSS.test(z) || RECHT.test(z)) { schnitt = i; schnittAmZitat = false; break; }
    if (ZITAT.test(z)) { schnitt = i; schnittAmZitat = true; break; }
  }
  const bis = schnitt === -1 ? zeilen.length : schnitt;

  let neu = "";
  for (let i = 0; i < bis; i++) {
    const z = zeilen[i];
    if (KONTAKT.test(z)) continue;
    if (PLZ.test(z)) continue;
    neu = neu + z + "\n";
  }
  neu = neu.replace(/\n{3,}/g, "\n\n").trim();

  const untergrenze = schnittAmZitat ? MIN_REST_ZEICHEN_ZITAT : MIN_REST_ZEICHEN;
  if (neu.length < untergrenze) { verworfenAnzahl += 1; return roh; }
  if (neu.length < roh.length) bereinigtAnzahl += 1;
  return neu;
}
// --- Ende M-5 -----------------------------------------------------------

const histories = (issue.changelog && Array.isArray(issue.changelog.histories)) ? issue.changelog.histories : [];
const statusHistory = [];
const levelHistory = [];
let assigneeChangeCount = 0;
for (const h of histories) {
  const at = String(h.created || "");
  const accountId = String((h.author && h.author.accountId) || "");
  const who = String((h.author && h.author.displayName) || "");
  const isAutomation = AUTOMATION.indexOf(accountId) !== -1;
  const items = Array.isArray(h.items) ? h.items : [];
  for (const it of items) {
    const fid = String((it.fieldId || it.field) || "");
    if (fid.toLowerCase() === "status") {
      statusHistory.push({ at: at, von: String(it.fromString || ""), nach: String(it.toString || ""), durch: who, automatisiert: isAutomation });
    } else if (fid === SUPPORT_FIELD || fid === "Support-Level") {
      levelHistory.push({ at: at, von: String(it.fromString || ""), nach: String(it.toString || ""), durch: who, automatisiert: isAutomation });
    } else if (fid.toLowerCase() === "assignee") {
      assigneeChangeCount += 1;
    }
  }
}
statusHistory.sort(function (a, b) { return String(a.at).localeCompare(String(b.at)); });
levelHistory.sort(function (a, b) { return String(a.at).localeCompare(String(b.at)); });

const manualLevel = levelHistory.filter(function (e) { return e.automatisiert !== true; });
const lastManual = manualLevel.length > 0 ? manualLevel[manualLevel.length - 1] : null;
const levelSetManually = lastManual !== null;
const levelLastSetAt = lastManual ? lastManual.at : "";
let statusChangedAfterLevel = statusHistory.length > 0;
if (levelSetManually) {
  statusChangedAfterLevel = statusHistory.some(function (s) { return String(s.at) > String(levelLastSetAt); });
}

const rawComments = (f.comment && Array.isArray(f.comment.comments)) ? f.comment.comments : [];
const comments = [];
for (const c of rawComments.slice(-14)) {
  const accountId = String((c.author && c.author.accountId) || "");
  const text = bereinigeText(adfText(c.body).replace(/\n{3,}/g, "\n\n").trim()).slice(0, 1500);
  if (!text) continue;
  comments.push({
    at: String(c.created || ""),
    autor: String((c.author && c.author.displayName) || ""),
    automatisiert: AUTOMATION.indexOf(accountId) !== -1,
    text: text
  });
}

const levelField = f[SUPPORT_FIELD] || null;
const statusId = String((f.status && f.status.id) || "");
const currentLevelValue = String((levelField && levelField.value) || "");

const hatMenschKommentar = comments.some(function (c) { return c.automatisiert !== true; });
const hatMenschStatus = statusHistory.some(function (s) { return s.automatisiert !== true; });
const frischesTicket = !hatMenschKommentar && !hatMenschStatus && (currentLevelValue === "" || currentLevelValue === "1st-Lvl.") && statusId !== STATUS_GWS;
const vorgabeVorhanden = cand.vorgabeVorhanden === true;

const result = {};
result.issueKey = String(issue.key || cand.issueKey || "");
result.source = String(cand.source || "unbekannt");
result.ausloeser = String(cand.ausloeser || "");
result.dryRun = cand.dryRun !== false;
result.jiraBaseUrl = String(cand.jiraBaseUrl || "https://rwg-r.atlassian.net");
result.vorgabeVorhanden = vorgabeVorhanden;
result.vorgabeScope = String(cand.vorgabeScope || "UNKNOWN");
result.vorgabeBusinessImpact = String(cand.vorgabeBusinessImpact || "UNKNOWN");
result.vorgabeBusinessProcess = String(cand.vorgabeBusinessProcess || "UNKNOWN");
result.vorgabeSecurityRisk = cand.vorgabeSecurityRisk === true;
result.bewertungNoetig = !(vorgabeVorhanden && frischesTicket);
result.summary = String(f.summary || "").slice(0, 500);
result.description = bereinigeText(adfText(f.description).replace(/\n{3,}/g, "\n\n").trim()).slice(0, 4000);
result.statusId = statusId;
result.statusName = String((f.status && f.status.name) || "");
result.assigneeName = String((f.assignee && f.assignee.displayName) || "");
result.assigneeChangeCount = assigneeChangeCount;
result.currentPriorityId = String((f.priority && f.priority.id) || "");
result.currentPriorityName = String((f.priority && f.priority.name) || "");
result.currentLevelId = String((levelField && levelField.id) || "");
result.currentLevelValue = currentLevelValue;
result.levelSetManually = levelSetManually;
result.levelLastSetAt = levelLastSetAt;
result.statusChangedAfterLevel = statusChangedAfterLevel;
result.statusHistory = statusHistory.slice(-15);
result.levelHistory = levelHistory.slice(-8);
result.comments = comments;
result.bereinigung = { bereinigt: bereinigtAnzahl, verworfen: verworfenAnzahl, minRestZeichen: MIN_REST_ZEICHEN, minRestZeichenZitat: MIN_REST_ZEICHEN_ZITAT };
return [{ json: result }];

// Leitet die Zielprioritaet aus den Betriebssignalen ab.
//
// GRUNDSATZ (fachliche Festlegung RWG):
//   Unterhalb von Medium liegen ausschliesslich planbare Anfragen.
//   Jede echte Stoerung ist mindestens Medium - auch wenn nur ein einzelner
//   Anwender betroffen ist. Wer nicht arbeiten kann, ist unternehmerisch ein
//   Schaden, unabhaengig von der Zahl der Betroffenen.
//   Niedrig und Sehr Niedrig sind daher nur bei SERVICE_REQUEST erreichbar.

const ctx = $("Ticketkontext aufbereiten").first().json || {};
const raw = $input.first().json || {};
const a = raw.output || {};
const uebersprungen = raw.bewertungUebersprungen === true;

const PRIORITY = {};
PRIORITY["1"] = { id: "1", name: "Sehr Hoch", rank: 5 };
PRIORITY["2"] = { id: "2", name: "Hoch", rank: 4 };
PRIORITY["3"] = { id: "3", name: "Medium", rank: 3 };
PRIORITY["4"] = { id: "4", name: "Niedrig", rank: 2 };
PRIORITY["5"] = { id: "5", name: "Sehr Niedrig", rank: 1 };
const SCOPES = ["UNKNOWN", "SINGLE_USER", "MULTIPLE_USERS", "SITE", "COMPANY"];
const IMPACTS = ["UNKNOWN", "CRITICAL_PROCESS_STOPPED", "MAJOR_RESTRICTION", "LIMITED", "SERVICE_REQUEST"];
const PROCS = ["UNKNOWN", "SALES", "LOGISTICS", "BILLING", "POS", "ERP", "PAYMENT", "OTHER"];
const OPERATIONAL = ["SALES", "LOGISTICS", "BILLING", "POS", "ERP", "PAYMENT"];
function up(v, d) { return String(v === null || v === undefined ? d : v).trim().toUpperCase(); }

const out = Object.assign({}, ctx);
out.bewertungUebersprungen = uebersprungen;
out.llmLevel = String(a.level || "");
out.llmConfidence = String(a.confidence || "").trim().toUpperCase();
out.llmEvidence = String(a.evidence || "").slice(0, 1500);
out.llmReason = String(a.reason || "").slice(0, 1000);
out.llmMissingInfo = String(a.missingInfo || "").slice(0, 500);

let scope = up(a.scope || ctx.vorgabeScope, "UNKNOWN");
if (SCOPES.indexOf(scope) === -1) scope = "UNKNOWN";
let businessImpact = up(a.businessImpact || ctx.vorgabeBusinessImpact, "UNKNOWN");
if (IMPACTS.indexOf(businessImpact) === -1) businessImpact = "UNKNOWN";
let businessProcess = up(a.businessProcess || ctx.vorgabeBusinessProcess, "UNKNOWN");
if (PROCS.indexOf(businessProcess) === -1) businessProcess = "UNKNOWN";
const securityRisk = (a.securityRisk === true) || (ctx.vorgabeSecurityRisk === true);

out.signalScope = scope;
out.signalBusinessImpact = businessImpact;
out.signalBusinessProcess = businessProcess;
out.signalSecurityRisk = securityRisk;
out.signalQuelle = uebersprungen ? "vorgabe" : "bewertung";

const currentPriorityId = String(ctx.currentPriorityId || "").trim();
const currentPriority = PRIORITY[currentPriorityId] || null;

if (scope === "UNKNOWN" && businessImpact === "UNKNOWN" && !securityRisk) {
  out.shouldUpdatePriority = false;
  out.priorityId = currentPriorityId;
  out.priorityName = String(ctx.currentPriorityName || "");
  out.priorityDirection = "unveraendert";
  out.priorityReason = "Keine belastbaren Betriebssignale; Prioritaet bleibt unangetastet.";
  return [{ json: out }];
}

const istStoerung = businessImpact !== "SERVICE_REQUEST";

let targetId = "3";
let priorityReason = "Stoerung ohne weitere Eskalationsmerkmale; Medium als Grundwert.";
if (securityRisk) {
  targetId = "1"; priorityReason = "Konkreter Sicherheitsverdacht.";
} else if (businessImpact === "CRITICAL_PROCESS_STOPPED" && scope === "COMPANY") {
  targetId = "1"; priorityReason = "Kritischer Prozess unternehmensweit gestoppt.";
} else if (businessImpact === "CRITICAL_PROCESS_STOPPED") {
  targetId = "2"; priorityReason = "Kritischer Prozess ist nach Ticketlage gestoppt.";
} else if (scope === "COMPANY") {
  targetId = "2"; priorityReason = "Unternehmensweit betroffen.";
} else if (scope === "SITE" && businessImpact === "MAJOR_RESTRICTION") {
  targetId = "2"; priorityReason = "Ganzer Standort mit wesentlicher Einschraenkung betroffen.";
} else if (businessImpact === "MAJOR_RESTRICTION" && (scope === "MULTIPLE_USERS" || scope === "SITE")) {
  targetId = "2"; priorityReason = "Wesentliche Einschraenkung fuer mehrere Anwender oder Standort.";
} else if (businessImpact === "SERVICE_REQUEST") {
  if (OPERATIONAL.indexOf(businessProcess) !== -1) { targetId = "4"; priorityReason = "Planbare Anfrage im operativen Umfeld ohne Stoerung."; }
  else { targetId = "5"; priorityReason = "Planbare Service-Anfrage ohne Betriebsbezug."; }
}

// Untergrenze: eine echte Stoerung faellt nie unter Medium.
if (istStoerung && PRIORITY[targetId].rank < 3) {
  targetId = "3";
  priorityReason = "Stoerung der Arbeitsfaehigkeit; mindestens Medium unabhaengig von der Zahl der Betroffenen.";
}

let targetPriority = PRIORITY[targetId];

// Guard 1: bewusst hoch gesetzte Tickets werden nie automatisch gesenkt.
if (currentPriority && currentPriority.rank >= 4 && targetPriority.rank < currentPriority.rank) {
  targetPriority = currentPriority; targetId = currentPriority.id;
  priorityReason = "Bestehende hohe Prioritaet (" + currentPriority.name + ") wird nicht automatisch gesenkt.";
}

// Guard 2: herabstufen nur bei planbarer Anfrage ohne Sicherheitsbezug.
const downgradeSafe = !securityRisk && businessImpact === "SERVICE_REQUEST";
if (currentPriority && targetPriority.rank < currentPriority.rank && !downgradeSafe) {
  targetPriority = currentPriority; targetId = currentPriority.id;
  priorityReason = "Herabstufung nur bei planbarer Anfrage zulaessig; bestehender Wert bleibt.";
}

const shouldUpdatePriority = targetPriority.id !== currentPriorityId;
let priorityDirection = "unveraendert";
if (shouldUpdatePriority && currentPriority) priorityDirection = targetPriority.rank > currentPriority.rank ? "hochgestuft" : "herabgestuft";
else if (shouldUpdatePriority) priorityDirection = "gesetzt";

out.priorityId = targetPriority.id;
out.priorityName = targetPriority.name;
out.priorityReason = priorityReason;
out.priorityDirection = priorityDirection;
out.shouldUpdatePriority = shouldUpdatePriority;
return [{ json: out }];

