// Bestimmt das Ziel-Support-Level und sichert es gegen Fehlentscheidungen ab.
//
// GRUNDSATZ (fachliche Festlegung RWG):
//   Kann nicht sicher bewertet werden, bleibt der bestehende Wert stehen.
//   Spaetere Ereignisse liefern womoeglich einen besseren Bewertungspunkt.
//   Ist gar kein Wert gesetzt, wird 1st-Lvl. nachgetragen - ein leeres Feld
//   ist nie ein gueltiger Zustand.
//   Es wird nichts nach aussen gemeldet. Der Workflow ist in sich abgeschlossen.

const c = $input.first().json || {};
const STATUS_GWS = "10373";
const LEVEL_ID = {};
LEVEL_ID["1st-Lvl."] = "10354";
LEVEL_ID["2nd-Lvl."] = "10355";
LEVEL_ID["3rd-Lvl."] = "10356";
const RANK = {};
RANK["1st-Lvl."] = 1;
RANK["2nd-Lvl."] = 2;
RANK["3rd-Lvl."] = 3;
const ALLOWED = ["1st-Lvl.", "2nd-Lvl.", "3rd-Lvl."];
const RETURN_EVIDENCE = /(zur(ue|ü)ckgegeben|zur(ue|ü)ck gegeben|r(ue|ü)ckgabe|zur(ue|ü)ck an|wieder an den (first|second))/i;

const out = Object.assign({}, c);
const currentLevel = String(c.currentLevelValue || "");
const currentRank = RANK[currentLevel] || 0;
const statusId = String(c.statusId || "");

let targetLevel = "";
let confidence = "";
let evidence = "";
let reason = "";
let missingInfo = "";
let decisionSource = "";

if (statusId === STATUS_GWS) {
  targetLevel = "3rd-Lvl.";
  confidence = "HIGH";
  evidence = "Status: " + String(c.statusName || "");
  reason = "Harte RWG-Regel: Status WARTEN AUF GWS bedeutet Third Level.";
  decisionSource = "rule";
} else if (c.bewertungUebersprungen === true) {
  targetLevel = currentLevel;
  confidence = "HIGH";
  evidence = "Erstbewertung ohne neue Evidenz";
  reason = "Frisches Ticket ohne dokumentierte Weitergabe; Support-Level bleibt auf dem Anlagewert.";
  decisionSource = "skip";
} else if (c.levelSetManually === true && c.statusChangedAfterLevel !== true) {
  targetLevel = currentLevel;
  confidence = "HIGH";
  evidence = "Manueller Eintrag vom " + String(c.levelLastSetAt || "");
  reason = "Manuell gesetztes Support-Level ohne nachfolgende Level-Uebergabe; Wert wird respektiert.";
  decisionSource = "rule";
} else {
  targetLevel = String(c.llmLevel || "");
  confidence = String(c.llmConfidence || "");
  evidence = String(c.llmEvidence || "");
  reason = String(c.llmReason || "");
  missingInfo = String(c.llmMissingInfo || "");
  decisionSource = "llm";
}

let shouldUpdateLevel = false;
let unsicher = false;
let levelDirection = "unveraendert";
let guardReason = "";

if (decisionSource === "skip") {
  guardReason = "Keine Bewertung noetig; Anlagewert bleibt bestehen.";
} else if (ALLOWED.indexOf(targetLevel) === -1) {
  unsicher = true;
  guardReason = "Kein zulaessiger Level-Wert ermittelt; bestehender Wert bleibt.";
  targetLevel = currentLevel;
} else if (decisionSource === "llm" && confidence !== "HIGH") {
  unsicher = true;
  guardReason = "Bewertungssicherheit unter HIGH; bestehender Wert bleibt bis zu einem besseren Bewertungspunkt.";
  targetLevel = currentLevel;
} else if (decisionSource === "llm" && evidence.trim().length < 10) {
  unsicher = true;
  guardReason = "Keine belastbare Fundstelle geliefert; bestehender Wert bleibt.";
  targetLevel = currentLevel;
} else if (targetLevel === currentLevel) {
  guardReason = "Zielwert entspricht dem Ist-Wert.";
} else {
  const targetRank = RANK[targetLevel] || 0;
  if (targetRank < currentRank && currentRank > 0) {
    if (decisionSource === "llm" && !RETURN_EVIDENCE.test(evidence)) {
      unsicher = true;
      guardReason = "Herabstufung ohne dokumentierte Rueckgabe verhindert; bestehender Wert bleibt.";
      targetLevel = currentLevel;
    } else {
      shouldUpdateLevel = true;
      levelDirection = "herabgestuft";
    }
  } else {
    shouldUpdateLevel = true;
    levelDirection = currentRank === 0 ? "gesetzt" : "hochgestuft";
  }
}

// Manuell gesetzte Werte nicht ohne eindeutigen Beleg ueberschreiben.
if (c.levelSetManually === true && shouldUpdateLevel && statusId !== STATUS_GWS && decisionSource === "llm" && confidence !== "HIGH") {
  shouldUpdateLevel = false;
  unsicher = true;
  guardReason = "Manuell gesetzter Wert wird ohne eindeutigen Beleg nicht ueberschrieben.";
  targetLevel = currentLevel;
  levelDirection = "unveraendert";
}

// Letzte Absicherung: ein leeres Feld ist nie ein gueltiger Zustand.
// Unabhaengig davon, warum kein Zielwert zustande kam, wird der Anlagewert
// 1st-Lvl. nachgetragen.
if (ALLOWED.indexOf(targetLevel) === -1) {
  targetLevel = "1st-Lvl.";
  shouldUpdateLevel = true;
  levelDirection = "gesetzt";
  guardReason = "Kein Support-Level gesetzt; Anlagewert 1st-Lvl. nachgetragen.";
}

out.levelDecisionSource = decisionSource;
out.targetLevelValue = targetLevel;
out.targetLevelId = LEVEL_ID[targetLevel] || "";
out.levelConfidence = confidence;
out.levelEvidence = evidence;
out.levelReason = reason;
out.levelMissingInfo = missingInfo;
out.levelGuardReason = guardReason;
out.levelDirection = levelDirection;
out.shouldUpdateLevel = shouldUpdateLevel;
out.levelUnsicher = unsicher;
// Das unsichere Ergebnis wird gemeldet, statt still verworfen zu werden.
